begin;
set local lock_timeout='3s'; set local statement_timeout='60s';
create function pg_temp.ok(b boolean,label text) returns void language plpgsql as $$begin if b is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end $$;
create function pg_temp.reject(q text,code text,label text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then raise notice 'PASS %',label;return;end if;raise exception 'FAIL % expected % got % %',label,code,sqlstate,sqlerrm;end;raise exception 'FAIL % accepted',label;end $$;
insert into public.integration_connections(id,organization_id,provider,display_name,status,secret_name,public_config,created_by)
values('99999999-9999-4999-8999-999999996910','99999999-9999-4999-8999-999999999901','openai','Local mapping rollback fixture','verified','ANKA_OPENAI_LOCAL_FIXTURE','{"model_id":"gpt-6.1-sol"}','99999999-9999-4999-8999-999999999902');
insert into public.integration_connection_departments(connection_id,organization_id,department_id,created_by)
select '99999999-9999-4999-8999-999999996910','99999999-9999-4999-8999-999999999901',d,'99999999-9999-4999-8999-999999999902' from unnest(array['content','design','marketing']) d;
insert into public.department_chat_model_configurations(organization_id,department_id,connector_connection_id,model_id,display_name,verified_at,created_by)
select '99999999-9999-4999-8999-999999999901',d,'99999999-9999-4999-8999-999999996910','gpt-6.1-sol','Sol fixture',now(),'99999999-9999-4999-8999-999999999902' from unnest(array['content','design','marketing']) d;
create function pg_temp.snapshot() returns jsonb language sql as $$select public.get_workshop_model_mappings('99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999975','99999999-9999-4999-8999-999999999902')$$;
create function pg_temp.save(q uuid,t text,s jsonb) returns jsonb language sql as $$select public.save_workshop_model_mappings('99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999975','99999999-9999-4999-8999-999999999902',q,t,s)$$;
select pg_temp.ok((select count(*)=3 from jsonb_array_elements(pg_temp.snapshot()->'candidates') x where x->>'connection_id'='99999999-9999-4999-8999-999999996910'),'three existing Workshop services eligible');
select pg_temp.ok(pg_temp.snapshot()::text not like '%ANKA_OPENAI_LOCAL_FIXTURE%','secret reference withheld');
select pg_temp.ok(not has_function_privilege('authenticated','public.save_workshop_model_mappings(uuid,uuid,uuid,uuid,uuid,text,jsonb)','execute'),'no direct authenticated actor spoof');
select pg_temp.ok(not has_function_privilege('anon','public.get_workshop_model_mappings(uuid,uuid,uuid,uuid)','execute'),'anon closed');
select pg_temp.ok((select relrowsecurity from pg_class where oid='private.workshop_model_mapping_receipts'::regclass),'receipt RLS closed');
select pg_temp.ok(not has_table_privilege('service_role','private.workshop_model_mapping_receipts','update,delete'),'receipt immutable to service');
select pg_temp.reject($q$select public.get_workshop_model_mappings('11111111-1111-4111-8111-111111111111','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999975','99999999-9999-4999-8999-999999999902')$q$,'42501','foreign org denied');
select pg_temp.reject($q$select public.get_workshop_model_mappings('99999999-9999-4999-8999-999999999901','11111111-1111-4111-8111-111111111111','99999999-9999-4999-8999-999999999975','99999999-9999-4999-8999-999999999902')$q$,'42501','mismatched project denied');
savepoint archived;
update public.projects set archived_at=now() where id='99999999-9999-4999-8999-999999999974';
select pg_temp.reject('select pg_temp.snapshot()','42501','archived project denied');
rollback to archived;
savepoint approved;
update public.department_chat_model_configurations set revoked_at=now(),revoked_by='99999999-9999-4999-8999-999999999902' where connector_connection_id='99999999-9999-4999-8999-999999996910';
select pg_temp.ok((select count(*)=0 from jsonb_array_elements(pg_temp.snapshot()->'candidates') x where x->>'connection_id'='99999999-9999-4999-8999-999999996910'),'revoked model approvals withheld');
rollback to approved;
savepoint service;
update public.engagement_services set status='planned' where engagement_id='99999999-9999-4999-8999-999999999975';
select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'candidates')=0,'inactive services withheld');
rollback to service;
savepoint leader;
update public.organization_memberships set role='contributor' where organization_id='99999999-9999-4999-8999-999999999901';
select pg_temp.reject('select pg_temp.snapshot()','42501','nonleader denied');
rollback to leader;
select set_config('qa.mapping_token',pg_temp.snapshot()->>'token',true);
select pg_temp.reject($q$select pg_temp.save(gen_random_uuid(),'bad','[]')$q$,'22023','empty rejected');
select pg_temp.reject($q$select pg_temp.save(gen_random_uuid(),'bad','[{"connection_id":"99999999-9999-4999-8999-999999996910","department_id":"content"}]')$q$,'40001','stale review rejected');
update public.integration_connections set status='configured' where id='99999999-9999-4999-8999-999999996910';
select pg_temp.ok((select count(*)=0 from jsonb_array_elements(pg_temp.snapshot()->'candidates') x where x->>'connection_id'='99999999-9999-4999-8999-999999996910'),'unverified connector withheld');
update public.integration_connections set status='verified' where id='99999999-9999-4999-8999-999999996910';
delete from public.integration_connection_departments where connection_id='99999999-9999-4999-8999-999999996910' and department_id='content';
select pg_temp.ok((select count(*)=2 from jsonb_array_elements(pg_temp.snapshot()->'candidates') x where x->>'connection_id'='99999999-9999-4999-8999-999999996910'),'department revoke withheld');
insert into public.integration_connection_departments(connection_id,organization_id,department_id,created_by) values('99999999-9999-4999-8999-999999996910','99999999-9999-4999-8999-999999999901','content','99999999-9999-4999-8999-999999999902');
do $$declare s jsonb;t text;res jsonb;retry jsonb; q uuid:=gen_random_uuid();begin
 select jsonb_agg(jsonb_build_object('connection_id',value->>'connection_id','department_id',value->>'department_id')) into s from jsonb_array_elements(pg_temp.snapshot()->'candidates') where value->>'connection_id'='99999999-9999-4999-8999-999999996910';
 t:=pg_temp.snapshot()->>'token';res:=pg_temp.save(q,t,s);retry:=pg_temp.save(q,t,s);
 perform pg_temp.ok(res=retry,'exact retry returns original response');
 perform pg_temp.ok(jsonb_array_length(res->'added')=3,'three additive mappings saved');
 perform pg_temp.ok((select count(*)=1 from private.workshop_model_mapping_receipts where request_id=q),'one receipt');
 perform pg_temp.ok((select count(*)=1 from public.engagement_events where payload->>'request_id'=q::text),'one audit event');
 perform pg_temp.reject(format('select pg_temp.save(%L,%L,%L)',q,'changed',s),'22023','UUID reuse changed payload rejected');
 perform pg_temp.ok(public.recover_workshop_model_mappings('99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999975','99999999-9999-4999-8999-999999999902',q)=res,'original read recovery');
 res:=pg_temp.save(gen_random_uuid(),pg_temp.snapshot()->>'token',s);
 perform pg_temp.ok(jsonb_array_length(res->'added')=0,'existing links preserved without duplicates');
end $$;
set local role service_role;
select pg_temp.ok(pg_temp.snapshot()->>'schema_version'='1','service-only invocation works');
reset role;
update public.organization_memberships set status='revoked' where organization_id='99999999-9999-4999-8999-999999999901' and user_id='99999999-9999-4999-8999-999999999902';
select pg_temp.reject('select pg_temp.snapshot()','42501','revoked membership rejected');
rollback;
